def completar_series(apps, schema_editor):
    from django.conf import settings
    emisor = settings.FACTURASEGURA.get('EMISOR', {})
    for nombre in ('FacturaElectronica', 'NotaCreditoElectronica'):
        Modelo = apps.get_model('facturacion', nombre)
        for documento in Modelo.objects.using(schema_editor.connection.alias).all().iterator():
            de = documento.de_enviado or {}
            partes = (documento.numero_completo or '').split('-')
            documento.establecimiento = str(de.get('dEst') or (partes[0] if len(partes) == 3 else emisor.get('dEst', '')))
            documento.punto_expedicion = str(de.get('dPunExp') or (partes[1] if len(partes) == 3 else emisor.get('dPunExp', '')))
            documento.timbrado = str(de.get('dNumTim') or emisor.get('dNumTim', ''))
            documento.save(update_fields=['establecimiento', 'punto_expedicion', 'timbrado'])


